    elif is_sequence(coords):
        for i in range(len(coords)):
            xy[i] = coords[i]

    if customer_ids is None:
        if is_mapping(demands_raw):
            customer_ids = [k for k in demands_raw.keys() if k != depot]
        elif is_mapping(coords):
            customer_ids = [k for k in coords.keys() if k != depot]
        elif is_sequence(dist_matrix):
            customer_ids = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customer_ids = []

    customer_ids = [c for c in customer_ids if c != depot]
    seen = {}
    uniq = []
    for c in customer_ids:
        if c not in seen:
            seen[c] = 1
            uniq.append(c)
    customer_ids = uniq

    def demand_of(c):
        try:
            return demands[c]
        except Exception:
            return 1

    def coord_of(c):
        try:
            return xy[c]
        except Exception:
            return None

    def dist(a, b):
        if dist_matrix is not None:
            try:
                return dist_matrix[a][b]
            except Exception:
                pass
        pa = coord_of(a)
        pb = coord_of(b)
        if pa is not None and pb is not None:
            ax, ay = pa[0], pa[1]
            bx, by = pb[0], pb[1]
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        return abs(a - b)

    depot_xy = coord_of(depot)
    if depot_xy is not None:
        dx, dy = depot_xy[0], depot_xy[1]
        def order_key(c):
            p = coord_of(c)
            if p is None:
                return (0, 0, c)
            x, y = p[0], p[1]
            return ((y - dy), (x - dx), c)
        customer_ids.sort(key=order_key)
    else:
        customer_ids.sort(key=lambda c: (-demand_of(c), c))

    unassigned = customer_ids[:]
    routes = []

    while unassigned:
        route = []
        load = 0
        current = depot

        best = None
        best_score = None
        for c in unassigned:
            d = demand_of(c)
            if capacity > 0 and d > capacity and not route:
                score = (dist(depot, c), d, c)
            elif capacity <= 0 or load + d <= capacity:
                score = (dist(depot, c), d, c)
            else:
                continue
            if best is None or score < best_score:
                best = c
                best_score = score

        if best is None:
            best = unassigned[0]

        route.append(best)
        load += demand_of(best)
        current = best
        unassigned.remove(best)

        while True:
            cand = None
            cand_score = None
            for c in unassigned:
                d = demand_of(c)
                if capacity > 0 and load + d > capacity:
                    continue
                score = (dist(current, c), dist(depot, c), d, c)
                if cand is None or score < cand_score:
                    cand = c
                    cand_score = score
            if cand is None:
                break
            route.append(cand)
            load += demand_of(cand)
            current = cand
            unassigned.remove(cand)

        routes.append(route)

    def route_load(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        total = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            total += dist(rt[i], rt[i + 1])
        total += dist(rt[-1], depot)
        return total

    def two_opt(rt):
        n = len(rt)
        if n < 4:
            return rt
        improved = True
        while improved:
            improved = False
            best_delta = 0
            bi = bj = None
            for i in range(n - 2):
                a = depot if i == 0 else rt[i - 1]
                b = rt[i]
                for j in range(i + 2, n):
                    c = rt[j]
                    d = depot if j == n - 1 else rt[j + 1]
                    delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                    if delta < best_delta:
                        best_delta = delta
                        bi, bj = i, j
            if bi is not None:
                rt = rt[:bi] + rt[bi:bj + 1][::-1] + rt[bj + 1:]
                improved = True
        return rt

    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])

    # Inter-route relocate improvement
    improved = True
    while improved:
        improved = False
        best_move = None
        best_gain = 0
        for i in range(len(routes)):
            ri = routes[i]
            li = route_load(ri)
            for pi in range(len(ri)):
                a = depot if pi == 0 else ri[pi - 1]
                x = ri[pi]
                b = depot if pi == len(ri) - 1 else ri[pi + 1]
                remove_delta = dist(a, b) - dist(a, x) - dist(x, b)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj)
                    dx = demand_of(x)
                    if capacity > 0 and lj + dx > capacity:
                        continue
                    for pj in range(len(rj) + 1):
                        u = depot if pj == 0 else rj[pj - 1]
                        v = depot if pj == len(rj) else rj[pj]
                        add_delta = dist(u, x) + dist(x, v) - dist(u, v)
                        gain = remove_delta - add_delta
                        if gain > best_gain:
                            best_gain = gain
                            best_move = (i, pi, j, pj)
        if best_move is not None:
            i, pi, j, pj = best_move
            x = routes[i][pi]
            routes[i].pop(pi)
            if j > i:
                j -= 1
            routes[j].insert(pj, x)
            routes = [r for r in routes if len(r) > 0]
            improved = True

    # Final cleanup: one more 2-opt pass
    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])

    return routes
